-- Customer freight/order-price ratio | postgres
-- Generated by scripts/export-demo-sql.ts; display formatting only.
-- Ordered sample parameters: [0,0,1]
-- r9 aggregate: merged; Compatible row-level input block
-- r6 project: merged; Compatible row-level input block
-- r3 project: merged; Compatible row-level input block
-- r2 aggregate: merged; Compatible row-level input block
-- r1 project: boundary; Preserve aggregate input scope or specialized lowering boundary
-- r0 sort: merged; Track output ordering without a new query block
select
  "r1"."c0" as "customer_id",
  cast(
    ("r1"."c1" / nullif("r1"."c2", 0)) as decimal(38, 10)
  ) as "freight_ratio"
from
  (
    select
      "r4"."customer_id" as "c0",
      cast(sum("r12"."c2") as decimal(38, 10)) as "c1",
      cast(sum("r12"."c1") as decimal(38, 10)) as "c2"
    from
      "customers" as "r4"
      left join (
        select
          "r7"."customer_id" as "c0",
          cast(
            coalesce("r11"."c1", cast($1 as integer)) as decimal(38, 10)
          ) as "c1",
          cast(
            coalesce(
              cast("r7"."freight" as decimal(38, 10)),
              cast($2 as integer)
            ) as decimal(38, 10)
          ) as "c2"
        from
          "orders" as "r7"
          left join (
            select
              "order_details"."order_id" as "c0",
              cast(
                sum(
                  cast(
                    (
                      cast(
                        (
                          cast("order_details"."unit_price" as decimal(38, 10)) * cast("order_details"."quantity" as decimal(38, 10))
                        ) as decimal(38, 10)
                      ) * cast(
                        (
                          cast(cast($3 as integer) as decimal(38, 10)) - cast("order_details"."discount" as decimal(38, 10))
                        ) as decimal(38, 10)
                      )
                    ) as decimal(38, 10)
                  )
                ) as decimal(38, 10)
              ) as "c1"
            from
              "order_details"
            group by
              "order_details"."order_id"
          ) as "r11" on ("r7"."order_id" = "r11"."c0")
      ) as "r12" on ("r4"."customer_id" = "r12"."c0")
    group by
      "r4"."customer_id"
  ) as "r1"
order by
  "r1"."c0" asc;
